#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

use plexdio::ui::runner::{self, RunnerOptions};
use plexdio::ui::theme;
use plexdio::ui::app::{LaunchOptions, PlexdioApp, TOKEN_NAME};
use plexdio::{config::Config, logging, paths, secure_store, win::single_instance};
use std::sync::Arc;

/// Raw 64x64 RGBA generated by tools/make_icons.py (no PNG decoder needed at runtime).
fn load_icon() -> egui::IconData {
    let rgba = include_bytes!("../../../assets/icon64.rgba");
    egui::IconData { rgba: rgba.to_vec(), width: 64, height: 64 }
}

fn main() {
    // Run by the uninstaller ([UninstallRun] in installer/plexdio.iss): remove what lives outside the
    // program folder and is not user data (the start-with-Windows entry), then exit. Settings,
    // caches and the saved sign-in stay.
    if std::env::args().skip(1).any(|a| a == "--uninstall") {
        plexdio::win::autostart::set_enabled(false);
        return;
    }
    paths::migrate_legacy_dirs();
    let log_path = logging::init(&paths::log_dir(), cfg!(debug_assertions));
    log::info!(
        "Plexdio {} starting ({}, data: {}; log: {})",
        env!("CARGO_PKG_VERSION"),
        paths::install_mode().label(),
        paths::config_dir().display(),
        log_path.display()
    );

    // Started by a portable self-update: the old process is still exiting, so wait for it
    // instead of handing over to it.
    let after_update = std::env::args().skip(1).any(|a| a == plexdio::update::portable::AFTER_UPDATE_FLAG);
    let mut guard = single_instance::acquire();
    if after_update {
        let until = std::time::Instant::now() + std::time::Duration::from_secs(30);
        while guard.is_none() && std::time::Instant::now() < until {
            std::thread::sleep(std::time::Duration::from_millis(250));
            guard = single_instance::acquire();
        }
    }
    let Some(_guard) = guard else {
        log::info!("another instance is running; activating it");
        single_instance::activate_existing();
        return;
    };
    // Remove what a portable self-update left behind (the previous exe). It may take a moment
    // until Windows lets go of the old process's image.
    if let Ok(exe) = std::env::current_exe() {
        std::thread::spawn(move || {
            for _ in 0..20 {
                if plexdio::update::portable::cleanup(&exe) {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(500));
            }
        });
    }

    let opts = LaunchOptions::from_args(std::env::args().skip(1));
    if let Some(u) = &opts.plex_tv_url {
        log::info!("using Plex endpoint override {u}");
    }
    let config = Config::load();
    // Re-assert the Run entry on every start so a moved exe keeps working.
    plexdio::win::autostart::apply(config.start_with_windows);
    let size = config.window_size.unwrap_or([1180.0, 760.0]);
    let options = RunnerOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title("Plexdio")
            .with_app_id("Plexdio")
            // The app draws its own themed title bar (ui/titlebar.rs).
            .with_decorations(false)
            .with_inner_size(size)
            .with_min_inner_size([760.0, 480.0])
            .with_icon(load_icon())
            .with_drag_and_drop(false),
        background: theme::BG,
    };
    let ctx = egui::Context::default();
    // CJK/emoji titles fall back to an installed system font instead of rendering as boxes.
    ctx.add_font_provider(Arc::new(plexdio::ui::fonts::system_provider()));
    if let Err(e) = runner::run(options, ctx, move |ctx, _proxy| {
        let store: Arc<dyn secure_store::SecretStore> = Arc::from(secure_store::default_store(TOKEN_NAME));
        PlexdioApp::new(ctx, config, opts, store)
    }) {
        log::error!("UI terminated with error: {e}");
    }
    log::info!("Plexdio exiting");
}
